/**
 * A língua do beija-flor — porte de `componentes/viz/beija_flor.js`.
 *
 * O beija-flor paira e lambe o néctar mais de dez vezes por segundo. A língua
 * não é um canudo que suga: ela se abre em duas metades que se fecham sobre o
 * néctar por capilaridade, e por isso existe um ritmo ÓTIMO — devagar desperdiça
 * o tempo em que ele está pairando (o voo mais caro que existe), e rápido demais
 * não dá tempo de a língua encher antes de sair.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const beijaFlor: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const ritmo = numeroDe(valores, 'fr', 0);
    const coleta = numeroDe(info, 'coleta', 0);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'O ritmo que enche a língua');

    // **A escala.** Tudo aqui era literal em pixels: o pássaro tinha 21 px de
    // corpo em qualquer tela, e no telefone era um borrão azul com um risco.
    const E = limitar(Math.min(L * 0.075, A * 0.115), 16, 38);

    // A flor.
    const fx = L * 0.74;
    const fy = A * 0.54;
    ctx.fillStyle = ok ? '#e0567f' : '#c9556f';
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      ctx.beginPath();
      ctx.ellipse(
        fx + Math.cos(a) * E * 1.1,
        fy + Math.sin(a) * E * 1.1,
        E * 0.78,
        E * 0.5,
        a,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
    ctx.fillStyle = '#6a3a1a';
    ctx.beginPath();
    ctx.arc(fx, fy, E * 0.6, 0, Math.PI * 2);
    ctx.fill();

    // ── O beija-flor ──────────────────────────────────────────────────────
    const bx = L * 0.3;
    const by = A * 0.48;
    const plumagem = ok ? '#2f9e74' : '#2f7fa0';
    const plumagemEscura = ok ? '#1f7355' : '#1f5c76';

    // A cauda em leque, atrás do corpo.
    ctx.fillStyle = plumagemEscura;
    ctx.save();
    ctx.translate(bx - E * 0.9, by + E * 0.3);
    ctx.rotate(0.35);
    for (const abertura of [-0.3, 0, 0.3]) {
      ctx.beginPath();
      ctx.ellipse(-E * 0.4, abertura * E * 0.4, E * 0.55, E * 0.12, abertura * 0.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    // A asa é um borrão de propósito: a 50 batidas por segundo é isso o que o
    // olho vê. Duas elipses cruzadas dão o oito que a asa descreve no ar.
    ctx.fillStyle = 'rgb(70 105 125 / 26%)';
    for (const sentido of [-1, 1]) {
      ctx.save();
      ctx.translate(bx - E * 0.15, by - E * 0.1);
      ctx.rotate(Math.sin(t * 30) * 0.5 + sentido * 0.5);
      ctx.beginPath();
      ctx.ellipse(0, 0, E * 1.35, E * 0.32, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // O corpo e a cabeça, no mesmo eixo — a cabeça é a continuação do corpo, e
    // é dela que o bico sai, na altura do olho.
    ctx.fillStyle = plumagem;
    ctx.beginPath();
    ctx.ellipse(bx, by, E, E * 0.62, -0.3, 0, Math.PI * 2);
    ctx.fill();

    // A gorja iridescente, a marca do bicho.
    ctx.fillStyle = ok ? '#7fd8a8' : '#d2416a';
    ctx.beginPath();
    ctx.ellipse(bx + E * 0.5, by + E * 0.08, E * 0.34, E * 0.24, -0.3, 0, Math.PI * 2);
    ctx.fill();

    const cabecaX = bx + E * 0.82;
    const cabecaY = by - E * 0.38;
    ctx.fillStyle = plumagem;
    ctx.beginPath();
    ctx.arc(cabecaX, cabecaY, E * 0.44, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.arc(cabecaX + E * 0.16, cabecaY - E * 0.1, E * 0.1, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgb(255 255 255 / 80%)';
    ctx.beginPath();
    ctx.arc(cabecaX + E * 0.13, cabecaY - E * 0.14, E * 0.04, 0, Math.PI * 2);
    ctx.fill();

    // ── O bico ────────────────────────────────────────────────────────────
    // Ele sai da cabeça e afila até a flor: era um traço de espessura fixa que
    // partia de um ponto solto no ar, ao lado do corpo.
    const bicoBaseX = cabecaX + E * 0.3;
    const bicoBaseY = cabecaY + E * 0.05;
    const bicoPontaX = fx - E * 0.62;
    const bicoPontaY = fy - E * 0.08;

    const dx = bicoPontaX - bicoBaseX;
    const dy = bicoPontaY - bicoBaseY;
    const norma = Math.hypot(dx, dy) || 1;
    const nx = -dy / norma;
    const ny = dx / norma;
    const meio = E * 0.11;

    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.moveTo(bicoBaseX + nx * meio, bicoBaseY + ny * meio);
    ctx.lineTo(bicoPontaX, bicoPontaY);
    ctx.lineTo(bicoBaseX - nx * meio, bicoBaseY - ny * meio);
    ctx.closePath();
    ctx.fill();

    // A língua bífida, saindo da PONTA DO BICO para dentro da flor.
    const piscada = Math.sin(t * Math.max(1, ritmo) * 1.6) * 0.5 + 0.5;
    const comprimento = E * (0.3 + piscada * (0.5 + ritmo * 0.02));
    ctx.strokeStyle = '#d2416a';
    ctx.lineWidth = Math.max(1.4, E * 0.06);
    ctx.lineCap = 'round';
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(bicoPontaX, bicoPontaY);
      ctx.lineTo(
        bicoPontaX + (dx / norma) * comprimento + nx * lado * E * 0.1,
        bicoPontaY + (dy / norma) * comprimento + ny * lado * E * 0.1,
      );
      ctx.stroke();
    }

    // O néctar já colhido, voltando com o pássaro.
    ctx.fillStyle = cor.ouro;
    for (let i = 0; i < Math.round(coleta / 18); i++) {
      const x = bx - E * 1.3 - i * E * 0.45;
      const y = by - E * 0.9 + ((t * 40 + i * 15) % (E * 1.4));
      ctx.beginPath();
      ctx.arc(x, y, E * 0.13, 0, Math.PI * 2);
      ctx.fill();
    }

    // A barra de coleta.
    const gx = L - 14;
    const gy = A * 0.18;
    const gh = A * 0.62;
    retangulo(ctx, gx, gy, 9, gh, 4, cor.trilho);
    const cheia = (gh * limitar(coleta, 0, 100)) / 100;
    retangulo(ctx, gx, gy + gh - cheia, 9, cheia, 4, ok ? cor.verde : cor.ouro);

    texto(
      ctx,
      `${ritmo} lambidas/s · néctar ${Math.round(coleta)}%`,
      L / 2,
      A * 0.95,
      limitar(A * 0.044, 10, 14),
      { cor: ok ? cor.verde : cor.fraco, peso: 700 },
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default beijaFlor;
